customCSS:
/* ==========================================================================
   AURELIA CHRONOMETRY — COMPREHENSIVE MOBILE RESPONSIVE ENGINE
   Configured in & driven exclusively from site-config.json
   ========================================================================== */

/* 1. Global Viewport & Container Containment */
html, body {
  overflow-x: hidden !important;
  max-width: 100vw !important;
  width: 100% !important;
  position: relative !important;
  box-sizing: border-box !important;
  -webkit-text-size-adjust: 100% !important;
}

*, *::before, *::after {
  box-sizing: border-box !important;
}

img, svg, video {
  max-width: 100% !important;
  height: auto;
}

/* 2. Announcement Bar & Ticker */
.announcement-bar {
  max-width: 100vw !important;
  overflow: hidden !important;
  box-sizing: border-box !important;
  padding: 8px 12px !important;
  font-size: 0.72rem !important;
}

.announcement-ticker {
  max-width: 100% !important;
  overflow: hidden !important;
}

/* 3. Site Header & Brand Lockup on Mobile */
@media (max-width: 768px) {
  .site-header {
    width: 100% !important;
    max-width: 100vw !important;
    padding-inline: 0 !important;
  }

  .header-container {
    width: 100% !important;
    max-width: 100vw !important;
    padding: 10px 14px !important;
    display: flex !important;
    align-items: center !important;
    justify-content: space-between !important;
    box-sizing: border-box !important;
    gap: 8px !important;
  }

  .mobile-nav-toggle {
    display: flex !important;
    flex-shrink: 0 !important;
    z-index: 10 !important;
  }

  .brand-link {
    display: flex !important;
    align-items: center !important;
    gap: 8px !important;
    min-width: 0 !important;
    flex: 1 1 auto !important;
    justify-content: flex-start !important;
  }

  .brand-crest {
    width: 32px !important;
    height: 32px !important;
    flex-shrink: 0 !important;
  }

  .brand-logo-img {
    max-width: 32px !important;
    max-height: 32px !important;
  }

  .brand-text-lockup {
    min-width: 0 !important;
  }

  .brand-name {
    font-size: 1.05rem !important;
    letter-spacing: 0.08em !important;
    white-space: nowrap !important;
    overflow: hidden !important;
    text-overflow: ellipsis !important;
  }

  .brand-sub {
    display: none !important;
  }

  .header-actions {
    display: flex !important;
    align-items: center !important;
    gap: 8px !important;
    flex-shrink: 0 !important;
  }

  .btn-header-auth {
    padding: 6px 10px !important;
    font-size: 0.78rem !important;
    white-space: nowrap !important;
  }

  .btn-cart-trigger {
    padding: 6px 10px !important;
  }
}

/* 4. Mystery Discount / Coupon Modal & Promo Banner */
.coupon-modal-card,
.promo-banner,
.mystery-discount-banner,
.floating-coupon-card {
  max-width: calc(100vw - 24px) !important;
  box-sizing: border-box !important;
  margin-inline: auto !important;
  overflow: hidden !important;
  word-break: break-word !important;
}

@media (max-width: 768px) {
  .promo-banner {
    padding: 20px 16px !important;
    margin: 16px 12px !important;
    border-radius: 16px !important;
  }
  .promo-banner h2, .promo-banner h3 {
    font-size: 1.25rem !important;
    line-height: 1.3 !important;
  }
  .promo-banner-code-box {
    flex-direction: column !important;
    gap: 8px !important;
    width: 100% !important;
  }
  .promo-banner-code-box .btn {
    width: 100% !important;
  }
}

/* 5. Hero Section: Mobile vs Desktop Split (Eliminates Dual Hero Overlap) */
@media (max-width: 767px) {
  /* Strictly hide the desktop 3-card flanking hero on mobile */
  .hero-section--flanking .hero-flanking-wrapper {
    display: none !important;
  }

  /* Show mobile hero showcase exclusively */
  .mobile-hero-showcase {
    display: block !important;
    position: relative !important;
    width: 100% !important;
    background-color: rgba(255, 255, 255, 0.04) !important;
    margin-bottom: 0 !important;
    padding-bottom: 20px !important;
  }

  .m-hero-scroll-track {
    position: relative !important;
    width: 100% !important;
    height: auto !important;
  }

  .m-hero-sticky-frame {
    position: relative !important;
    top: auto !important;
    height: auto !important;
    width: 100% !important;
    display: flex !important;
    flex-direction: column !important;
    align-items: center !important;
    padding: 10px 14px 16px !important;
    box-sizing: border-box !important;
  }

  .m-hero-stage--heading {
    text-align: center !important;
    margin-bottom: 12px !important;
    width: 100% !important;
    max-width: 420px !important;
  }

  .m-hero-title {
    font-size: clamp(1.4rem, 6vw, 1.85rem) !important;
    font-weight: 800 !important;
    line-height: 1.2 !important;
    color: #0F291E !important;
    margin: 0 !important;
  }

  .m-title-accent,
  .title-italic-accent {
    color: #064E3B !important;
    font-style: italic !important;
  }

  .m-hero-products-row {
    display: grid !important;
    grid-template-columns: 1fr 1fr !important;
    gap: 12px !important;
    width: 100% !important;
    max-width: 360px !important;
    margin: 0 auto 12px auto !important;
  }

  .m-hero-product-col {
    display: flex !important;
    flex-direction: column !important;
    align-items: center !important;
    text-align: center !important;
  }

  .m-bottle-pill {
    font-size: 0.625rem !important;
    font-weight: 800 !important;
    letter-spacing: 0.06em !important;
    padding: 2px 8px !important;
    border-radius: 999px !important;
    background: rgba(6, 78, 59, 0.08) !important;
    border: 1px solid #064E3B !important;
    color: #064E3B !important;
    margin-bottom: 4px !important;
  }

  .m-bottle-pill--shampoo {
    border-color: #E2B755 !important;
    color: #B45309 !important;
    background: rgba(226, 183, 85, 0.12) !important;
  }

  .m-bottle-box {
    width: 100% !important;
    height: 135px !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    margin-bottom: 4px !important;
  }

  .m-bottle-img {
    max-height: 125px !important;
    width: auto !important;
    max-width: 100% !important;
    object-fit: contain !important;
    filter: drop-shadow(0 8px 16px rgba(0, 0, 0, 0.15)) !important;
  }

  .m-bottle-meta {
    margin-bottom: 6px !important;
  }

  .m-bottle-name {
    font-size: 0.8rem !important;
    font-weight: 700 !important;
    color: #0F291E !important;
    white-space: nowrap !important;
    overflow: hidden !important;
    text-overflow: ellipsis !important;
    max-width: 150px !important;
  }

  .m-bottle-sub {
    font-size: 0.75rem !important;
    font-weight: 700 !important;
    color: #064E3B !important;
    margin-top: 2px !important;
  }

  .m-hero-product-col--shampoo .m-bottle-sub {
    color: #B45309 !important;
  }

  .m-hero-stage--buy-oil .m-btn-buy,
  .m-btn-buy {
    width: 100% !important;
    max-width: 130px !important;
    padding: 8px 14px !important;
    border-radius: 999px !important;
    background-color: #064E3B !important;
    color: #FFFFFF !important;
    font-size: 0.8rem !important;
    font-weight: 700 !important;
    letter-spacing: 0.03em !important;
    border: none !important;
    cursor: pointer !important;
    box-shadow: 0 4px 12px rgba(6, 78, 59, 0.28) !important;
  }

  .m-hero-stage--buy-shampoo .m-btn-buy,
  .m-btn-buy--shampoo {
    background-color: #1E293B !important;
    box-shadow: 0 4px 12px rgba(30, 41, 59, 0.28) !important;
  }

  .m-hero-stage--desc {
    max-width: 340px !important;
    margin: 0 auto 12px auto !important;
    text-align: center !important;
  }

  .m-hero-desc {
    font-size: 0.82rem !important;
    color: #52796F !important;
    line-height: 1.45 !important;
  }

  .m-hero-stage--cta {
    width: 100% !important;
    max-width: 320px !important;
    margin: 0 auto !important;
  }

  .m-cta-group {
    display: flex !important;
    flex-direction: column !important;
    gap: 8px !important;
    width: 100% !important;
  }

  .m-cta-btn {
    width: 100% !important;
    padding: 10px 18px !important;
    font-size: 0.82rem !important;
    border-radius: 999px !important;
    text-align: center !important;
    justify-content: center !important;
    display: inline-flex !important;
    align-items: center !important;
    text-decoration: none !important;
  }

  .m-cta-btn--primary {
    background: #064E3B !important;
    color: #FFFFFF !important;
    border: none !important;
    box-shadow: 0 4px 14px rgba(6, 78, 59, 0.3) !important;
  }

  .m-cta-btn--secondary {
    background: transparent !important;
    border: 1.5px solid #064E3B !important;
    color: #064E3B !important;
  }
}

/* Tablet view only (768px to 992px) */
@media (min-width: 768px) and (max-width: 992px) {
  .mobile-hero-showcase {
    display: none !important;
  }

  .hero-flanking-wrapper {
    display: flex !important;
    flex-direction: column !important;
    align-items: center !important;
    width: 100% !important;
    max-width: 100vw !important;
    padding-inline: 14px !important;
    box-sizing: border-box !important;
    gap: 20px !important;
    overflow: hidden !important;
  }

  .hero-center-content {
    order: -1 !important;
    width: 100% !important;
    max-width: 100% !important;
    padding: 10px 0 !important;
  }

  .hero-title {
    font-size: clamp(1.65rem, 6vw, 2.3rem) !important;
    line-height: 1.25 !important;
  }

  .hero-description {
    font-size: 0.95rem !important;
    line-height: 1.5 !important;
    padding-inline: 4px !important;
  }

  .hero-cta-group {
    display: flex !important;
    flex-direction: column !important;
    width: 100% !important;
    gap: 10px !important;
  }

  .hero-cta-group .btn {
    width: 100% !important;
    text-align: center !important;
    justify-content: center !important;
    padding: 14px 20px !important;
  }

  .hero-product-flank {
    width: 100% !important;
    max-width: 380px !important;
    margin: 0 auto !important;
  }

  .hero-flank-card {
    width: 100% !important;
    max-width: 100% !important;
    box-sizing: border-box !important;
    margin: 0 auto !important;
  }

  .hero-pillars {
    width: 100% !important;
    max-width: 100% !important;
    box-sizing: border-box !important;
    gap: 12px !important;
    padding: 16px !important;
  }
}

/* Desktop view (>= 993px) */
@media (min-width: 993px) {
  .mobile-hero-showcase {
    display: none !important;
  }
}

/* 6. Marquee Ticker */
.marquee-section {
  width: 100% !important;
  max-width: 100vw !important;
  overflow: hidden !important;
}

.marquee-track {
  width: max-content !important;
}

/* 7. 18-Module Circular Orbit Section (Clean Mobile View, No Node Collisions) */
@media (max-width: 768px) {
  .herbal-ingredients-section {
    padding-block: 40px 30px !important;
    width: 100% !important;
    max-width: 100vw !important;
    overflow: hidden !important;
  }

  .ingredients-section-header {
    padding-inline: 16px !important;
    margin-bottom: 20px !important;
    text-align: center !important;
  }

  .ingredients-section-header .section-heading {
    font-size: clamp(1.35rem, 5vw, 1.85rem) !important;
  }

  .ingredients-section-header .section-subtext {
    font-size: 0.88rem !important;
    line-height: 1.5 !important;
  }

  .orbit-stage-wrapper {
    width: 100% !important;
    max-width: 100vw !important;
    padding: 10px 4px !important;
    overflow: hidden !important;
    box-sizing: border-box !important;
    display: flex !important;
    justify-content: center !important;
  }

  .orbit-stage {
    --orbit-radius: 125px !important;
    width: 320px !important;
    height: 320px !important;
    max-width: 95vw !important;
    margin: 0 auto !important;
    position: relative !important;
  }

  .orbit-ring--outer {
    width: 250px !important;
    height: 250px !important;
  }

  .orbit-ring--middle {
    width: 200px !important;
    height: 200px !important;
  }

  .orbit-ring--inner {
    width: 160px !important;
    height: 160px !important;
  }

  .orbit-center-bottle-wrap {
    width: 110px !important;
    height: 110px !important;
    display: flex !important;
    flex-direction: column !important;
    align-items: center !important;
    justify-content: center !important;
    position: absolute !important;
    top: 50% !important;
    left: 50% !important;
    transform: translate(-50%, -50%) !important;
    z-index: 5 !important;
  }

  .orbit-center-bottle {
    max-width: 75px !important;
    max-height: 75px !important;
    object-fit: contain !important;
  }

  .bottle-caption-badge {
    position: static !important;
    bottom: auto !important;
    left: auto !important;
    transform: none !important;
    margin-top: 4px !important;
    font-size: 0.52rem !important;
    padding: 2px 6px !important;
    white-space: nowrap !important;
    max-width: 110px !important;
    overflow: hidden !important;
    text-overflow: ellipsis !important;
    box-sizing: border-box !important;
    background: rgba(6, 78, 59, 0.95) !important;
    color: #E2B755 !important;
    border: 1px solid rgba(226, 183, 85, 0.6) !important;
    border-radius: 999px !important;
  }

  .orbit-node {
    width: 28px !important;
    height: 28px !important;
  }

  .orbit-node .node-avatar-wrap {
    width: 28px !important;
    height: 28px !important;
  }

  .orbit-node .node-avatar-icon {
    font-size: 0.88rem !important;
  }

  .orbit-node .node-label {
    display: none !important;
  }

  .orbit-idle-card,
  .spotlight-card {
    width: calc(100vw - 32px) !important;
    max-width: 360px !important;
    margin: 16px auto !important;
    padding: 12px 14px !important;
    box-sizing: border-box !important;
  }
}

@media (max-width: 380px) {
  .orbit-stage {
    --orbit-radius: 110px !important;
    width: 285px !important;
    height: 285px !important;
  }

  .orbit-center-bottle {
    max-width: 65px !important;
    max-height: 65px !important;
  }

  .bottle-caption-badge {
    font-size: 0.48rem !important;
    max-width: 95px !important;
  }
}

/* 8. Products & Collection Grid on Mobile */
@media (max-width: 768px) {
  .collection-grid,
  .products-grid {
    display: flex !important;
    flex-direction: column !important;
    align-items: center !important;
    width: 100% !important;
    padding-inline: 12px !important;
    gap: 22px !important;
    box-sizing: border-box !important;
  }

  .product-card {
    width: 100% !important;
    max-width: 380px !important;
    box-sizing: border-box !important;
    margin: 0 auto !important;
    border-radius: 20px !important;
    overflow: hidden !important;
  }

  .card-inner {
    padding: 22px 18px !important;
    box-sizing: border-box !important;
  }

  .card-top-bar {
    margin-bottom: 12px !important;
    display: flex !important;
    align-items: center !important;
    justify-content: space-between !important;
    width: 100% !important;
  }

  .card-top-bar .pill-tag {
    font-size: 0.72rem !important;
    padding: 4px 10px !important;
    max-width: 200px !important;
    white-space: nowrap !important;
    overflow: hidden !important;
    text-overflow: ellipsis !important;
  }

  .circle-badge {
    width: 44px !important;
    height: 44px !important;
    min-width: 44px !important;
    min-height: 44px !important;
    padding: 2px !important;
  }

  .circle-badge .badge-number {
    font-size: 0.65rem !important;
  }

  .circle-badge .badge-unit {
    font-size: 0.52rem !important;
  }

  .card-image-wrap {
    height: 190px !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    margin-bottom: 10px !important;
  }

  .card-image-wrap img {
    max-height: 180px !important;
    object-fit: contain !important;
  }

  .product-card-title {
    font-size: 1.35rem !important;
    line-height: 1.25 !important;
    margin-bottom: 6px !important;
  }

  .product-card-subtitle {
    font-size: 0.82rem !important;
    line-height: 1.4 !important;
    margin-bottom: 10px !important;
  }

  .product-card-desc {
    font-size: 0.85rem !important;
    line-height: 1.5 !important;
    margin-bottom: 16px !important;
  }

  .card-action-bar,
  .product-card-pricing {
    display: flex !important;
    flex-direction: row !important;
    align-items: center !important;
    justify-content: space-between !important;
    width: 100% !important;
    gap: 8px !important;
  }

  .card-pricing,
  .price-group {
    display: flex !important;
    align-items: baseline !important;
    gap: 6px !important;
  }

  .btn-quick-add,
  .btn-add-to-bag,
  .btn-card-add {
    white-space: nowrap !important;
    padding: 10px 16px !important;
    min-width: 110px !important;
    font-size: 0.85rem !important;
    flex-shrink: 0 !important;
    line-height: 1.2 !important;
    border-radius: 999px !important;
  }
}

/* 9. Bundle Banner (Collector's Duo) */
@media (max-width: 768px) {
  .bundle-banner {
    padding: 22px 16px !important;
    margin: 20px 12px !important;
    width: auto !important;
    max-width: calc(100vw - 24px) !important;
    box-sizing: border-box !important;
    overflow: hidden !important;
    border-radius: 20px !important;
  }

  .bundle-banner-grid {
    display: flex !important;
    flex-direction: column !important;
    gap: 16px !important;
    width: 100% !important;
  }

  .bundle-banner-title {
    font-size: 1.35rem !important;
    word-break: break-word !important;
    line-height: 1.25 !important;
  }

  .bundle-banner-desc {
    font-size: 0.88rem !important;
    line-height: 1.5 !important;
  }

  .bundle-pricing {
    display: flex !important;
    align-items: baseline !important;
    flex-wrap: wrap !important;
    gap: 8px !important;
  }

  .bundle-banner-cta .btn {
    width: 100% !important;
    text-align: center !important;
    justify-content: center !important;
  }
}

/* 10. Reviews Section & Carousel on Mobile */
@media (max-width: 768px) {
  .reviews-section {
    padding-block: 40px 30px !important;
    width: 100% !important;
    max-width: 100vw !important;
    overflow: hidden !important;
  }

  .reviews-header {
    display: flex !important;
    flex-direction: column !important;
    align-items: center !important;
    text-align: center !important;
    gap: 14px !important;
    padding-inline: 14px !important;
    width: 100% !important;
  }

  .reviews-header-info {
    width: 100% !important;
  }

  .reviews-header-action {
    width: 100% !important;
    display: flex !important;
    justify-content: center !important;
  }

  .btn-comment-review {
    width: 100% !important;
    max-width: 280px !important;
    justify-content: center !important;
    padding: 12px 20px !important;
  }

  .reviews-scroller-viewport {
    width: 100% !important;
    max-width: 100vw !important;
    overflow-x: auto !important;
    -webkit-overflow-scrolling: touch !important;
    padding: 10px 12px 20px !important;
    box-sizing: border-box !important;
  }

  .reviews-scroller-track {
    display: flex !important;
    gap: 14px !important;
    width: max-content !important;
  }

  .review-card {
    width: 290px !important;
    min-width: 290px !important;
    max-width: 85vw !important;
    box-sizing: border-box !important;
    padding: 20px 16px !important;
    flex-shrink: 0 !important;
  }

  .reviews-edge-nav {
    display: none !important;
  }
}

/* 11. Science / Triad Grid */
@media (max-width: 768px) {
  .science-section {
    padding-block: 40px 30px !important;
    width: 100% !important;
    max-width: 100vw !important;
    overflow: hidden !important;
  }

  .triad-grid {
    display: flex !important;
    flex-direction: column !important;
    gap: 16px !important;
    width: 100% !important;
    padding-inline: 14px !important;
    box-sizing: border-box !important;
  }

  .triad-card {
    width: 100% !important;
    max-width: 100% !important;
    box-sizing: border-box !important;
    padding: 24px 18px !important;
  }
}

/* 12. Quote Section */
@media (max-width: 768px) {
  .quote-section {
    padding-block: 40px 30px !important;
    padding-inline: 16px !important;
    width: 100% !important;
    max-width: 100vw !important;
    overflow: hidden !important;
  }

  .quote-container,
  .quote-layout {
    display: flex !important;
    flex-direction: column !important;
    align-items: center !important;
    text-align: center !important;
    width: 100% !important;
  }

  .quote-image-wrap {
    width: 170px !important;
    height: 170px !important;
    margin: 0 auto 16px !important;
  }

  .quote-text {
    font-size: 1.1rem !important;
    line-height: 1.55 !important;
  }
}

/* 13. Newsletter Form */
@media (max-width: 768px) {
  .newsletter-section {
    padding-block: 40px 30px !important;
    padding-inline: 14px !important;
    width: 100% !important;
    max-width: 100vw !important;
    overflow: hidden !important;
  }

  .newsletter-form,
  .form-input-group {
    display: flex !important;
    flex-direction: column !important;
    width: 100% !important;
    max-width: 100% !important;
    gap: 10px !important;
    background: transparent !important;
    border: none !important;
    padding: 0 !important;
    box-sizing: border-box !important;
  }

  .newsletter-form input[type="email"] {
    width: 100% !important;
    border-radius: 999px !important;
    padding: 14px 20px !important;
    background: rgba(255, 255, 255, 0.1) !important;
    border: 1px solid rgba(255, 255, 255, 0.25) !important;
    box-sizing: border-box !important;
